/** The shipped manifest (install/manifest.json): ['version','generated_at','files' => [path => [sha256, size]]]. */
function cp_manifest(): ?array {
    $f = dirname(__DIR__) . '/install/manifest.json';
    if (!is_file($f)) return null;
    $m = json_decode((string) file_get_contents($f), true);
    return is_array($m) && isset($m['files']) ? $m : null;
}

/** Compare the live files with the manifest. Paths are relative to public_html (the portal root). */
function cp_integrity(): array {
    $m = cp_manifest();
    $root = dirname(__DIR__, 2);
    $out = ['manifest' => $m, 'ok' => [], 'modified' => [], 'missing' => [], 'extra' => [], 'checked' => 0];
    if (!$m) return $out;
    foreach ($m['files'] as $path => $info) {
        $p = $root . '/' . $path; $out['checked']++;
        if (!is_file($p)) { $out['missing'][] = $path; continue; }
        $h = hash_file('sha256', $p);
        if ($h === $info['sha256']) $out['ok'][] = $path;
        else $out['modified'][] = ['path' => $path, 'live_size' => filesize($p), 'size' => $info['size'], 'mtime' => date('Y-m-d H:i', filemtime($p))];
    }
    // files on the server that the manifest does not know (an older patch's leftovers, or something new)
    foreach (['customer/app', 'customer/views', 'customer/lang', 'customer/install', 'assets', 'employee/app', 'employee/assets'] as $dir) {
        $d = $root . '/' . $dir; if (!is_dir($d)) continue;
        foreach (new RecursiveIteratorIterator(new RecursiveDirectoryIterator($d, FilesystemIterator::SKIP_DOTS)) as $f) {
            $rel = str_replace('\\', '/', substr($f->getPathname(), strlen($root) + 1));
            if (preg_match('#/(config\.php|manifest\.json)$|/storage/|\.(log|bak|tmp)$#', $rel)) continue;
            if (!isset($m['files'][$rel]) && preg_match('/\.(php|js|css|sql|png|jpg|xlsx|ttf|json|md)$/i', $rel)) $out['extra'][] = $rel;
        }
    }
    sort($out['extra']);
    return $out;
}
